    "codeSnippet": {
      "filename": "app.py",
      "language": "python",
      "code": "from flask import Flask, render_template, request\nimport os\n\nimport tensorflow as tf\nfrom tensorflow.keras.models import load_model  # type: ignore\nfrom tensorflow.keras.preprocessing import image  # type: ignore\nfrom tensorflow.keras.metrics import AUC  # type: ignore\nimport numpy as np\n\n\napp = Flask(__name__)\n\n\n# ---------------------------------------------------------\n# PROJECT PATHS\n# ---------------------------------------------------------\n\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\n\nMODEL_PATH = os.path.join(BASE_DIR, \"model\", \"skin.h5\")\nTESTS_DIR = os.path.join(BASE_DIR, \"static\", \"tests\")\n\n# Make sure the tests folder exists\nos.makedirs(TESTS_DIR, exist_ok=True)\n\n\n# ---------------------------------------------------------\n# MODEL / DEPENDENCIES\n# ---------------------------------------------------------\n\ndependencies = {\n    \"auc_roc\": AUC\n}\n\n\nverbose_name = {\n    0: \"Actinic keratoses and intraepithelial carcinomae\",\n    1: \"Basal cell carcinoma\",\n    2: \"Benign keratosis-like lesions\",\n    3: \"Dermatofibroma\",\n    4: \"Melanocytic nevi\",\n    5: \"Pyogenic granulomas and hemorrhage\",\n    6: \"Melanoma\",\n}\n\n\n# ---------------------------------------------------------\n# LOAD MODEL\n# ---------------------------------------------------------\n\nmodel = load_model(MODEL_PATH)\n\n\n# ---------------------------------------------------------\n# PREDICTION FUNCTION\n# ---------------------------------------------------------\n\ndef predict_label(img_path):\n    test_image = image.load_img(\n        img_path,\n        target_size=(28, 28)\n    )\n\n    test_image = image.img_to_array(test_image) / 255.0\n\n    test_image = test_image.reshape(\n        1,\n        28,\n        28,\n        3\n    )\n\n    predict_x = model.predict(test_image)\n\n    classes_x = np.argmax(\n        predict_x,\n        axis=1\n    )\n\n    return verbose_name[classes_x[0]]\n\n\n# ---------------------------------------------------------\n# HOME\n# ---------------------------------------------------------\n\n@app.route(\"/\")\n@app.route(\"/first\")\ndef first():\n    return render_template(\"first.html\")\n\n\n# ---------------------------------------------------------\n# LOGIN\n# ---------------------------------------------------------\n\n@app.route(\"/login\")\ndef login():\n    return render_template(\"login.html\")\n\n\n# ---------------------------------------------------------\n# INDEX / UPLOAD PAGE\n# ---------------------------------------------------------\n\n@app.route(\"/index\", methods=[\"GET\", \"POST\"])\ndef index():\n    return render_template(\"index.html\")\n\n\n# ---------------------------------------------------------\n# IMAGE SUBMISSION / PREDICTION\n# ---------------------------------------------------------\n\n@app.route(\"/submit\", methods=[\"GET\", \"POST\"])\ndef get_output():\n\n    if request.method == \"POST\":\n\n        # Check whether a file was uploaded\n        if \"my_image\" not in request.files:\n            return \"No image file was uploaded.\", 400\n\n        img = request.files[\"my_image\"]\n\n        # Check whether a filename exists\n        if img.filename == \"\":\n            return \"No image was selected.\", 400\n\n        # Create a safe file path\n        img_path = os.path.join(\n            TESTS_DIR,\n            img.filename\n        )\n\n        # Save uploaded image\n        img.save(img_path)\n\n        # Predict\n        predict_result = predict_label(img_path)\n\n        # Convert filesystem path to a URL path for the browser\n        relative_img_path = os.path.relpath(\n            img_path,\n            BASE_DIR\n        ).replace(os.sep, \"/\")\n\n        relative_img_path = \"/\" + relative_img_path\n\n        return render_template(\n            \"prediction.html\",\n            prediction=predict_result,\n            img_path=relative_img_path\n        )\n\n    return render_template(\"index.html\")\n\n\n# ---------------------------------------------------------\n# RUN APPLICATION\n# ---------------------------------------------------------\n\nif __name__ == \"__main__\":\n    app.run(debug=True)"
    },
